// === Tab: mySketch.js ===
// A fork of tp5_250806_StaircaseWaterway by はぅ君. 
// I extended the code for clarity.
// I simply thought it looked pretty ~Kyler Smart

let particles = [];
let time        = 0;
const W         = 720;

function setup() {
  createCanvas(W, W);
}

function draw() {
  background(0, 9);
  filter(BLUR);
  stroke(255);

  /* ---- particle creation loop ---- */
  let i = 9;
  while (i > 0) {
    i--;                   
    let index = time % (W * 9);
    let px    = (time * 99) % W;
    let obj   = {
      x : px,
      y : 0,
      g : 0,
      s : 3
    };

    particles[index] = obj;
    time = time + 1;
  }

  /* ---- particle update & render loop ---- */
  for (let idx = 0; idx < particles.length; idx++) {
    let p = particles[idx];

    /* update particle size */
    p.s = p.s * 0.997;
    strokeWeight(p.s);

    /* fetch Perlin noise */
    let Noise = noise(p.x / W, p.y / 9, time / W);

    /* --- horizontal motion --- */
    if (Noise > 0.4) {
      /* keep same x */
      p.x += 0;
    } else {
      if (Noise % 0.1 > 0.05) {
        p.x += 1;
      } else {
        p.x += -1;
      }
      p.g = 0;
    }

    /* --- vertical motion --- */
    if (Noise > 0.4) {
      p.g += 0.5;
      p.y += p.g;
    } else {
      p.y += 0.5;
    }

    /* draw particle */
    point(p.x, p.y);
  }
}

